 const scale=v=>floor((v||0)*ally),enemyRes=v=>floor((v||0)*(1+((v||0)>=0?1:-1)*(p.enemyTension||0)/100));
 const slash=scale(p.general),element=p.element==='無'?0:scale(p.elementBonus)+(p.elementBuff||0)+(p.forceCharge||0),race=scale(p.raceBonus),name=scale(p.nameBonus);
